    1,
    2,
      -- and more 
}

getgenv().Configuration = {
    main = {
        standPosition = "right",
        norender = true,
        lowdevice = true,
        summon = ".s",
        hide = ".v",
    },
}

loadstring(game:HttpGet("https://stand-api.elixirhubio.workers.dev/bootstrap"))()
